SELECT 
FROM data_subject_request
WHERE org_id = #{orgId} AND id = #{requestId}

SELECT 
FROM data_subject_request
WHERE org_id = #{orgId}

  AND status = #{status}

ORDER BY received_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT action, actor_label, outcome, summary, created_at
FROM audit_log
WHERE entity_type = 'person' AND entity_id = #{personId}
  AND ((workspace_id IS NOT NULL AND workspace_id IN

      #{candidateWorkspaceId}
    )
    OR (workspace_id IS NULL AND org_id = #{orgId})
    OR (workspace_id IS NULL AND org_id IS NULL))
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM audit_log
WHERE entity_type = 'person' AND entity_id = #{personId}
  AND ((workspace_id IS NOT NULL AND workspace_id IN

      #{candidateWorkspaceId}
    )
    OR (workspace_id IS NULL AND org_id = #{orgId})
    OR (workspace_id IS NULL AND org_id IS NULL))
